function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 50) return 'nums needs 2 to 50 values.';
  if (nums.length % 2 !== 0) return 'nums needs an even number of values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Each value is a whole number from 1 to 50.';
  return null;
}

