function minimumAverage(nums) {
  nums.sort((a, b) => a - b);
  let left = 0;
  let right = nums.length - 1;
  let best = Infinity;
  while (left < right) {
    const average = (nums[left] + nums[right]) / 2;
    best = Math.min(best, average);
    left++;
    right--;
  }
  return best;
}

