function minimumAverage(nums) {
  // Follow the rounds literally: search out the smallest and largest, remove them, record the mean.
  const rest = nums.slice();
  const means = [];
  while (rest.length > 0) {
    const low = Math.min(...rest);
    rest.splice(rest.indexOf(low), 1);
    const high = Math.max(...rest);
    rest.splice(rest.indexOf(high), 1);
    means.push((low + high) / 2);
  }
  return Math.min(...means);
}

